"""ORM models of the tickets tables, used only inside the tickets adapters (PY-39)."""

from datetime import datetime
from uuid import UUID

from sqlalchemy import BigInteger, Computed, DateTime, Text, text
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column


class TicketsTables(DeclarativeBase):
    """The declarative base of the tables that tickets owns."""


class TicketRow(TicketsTables):
    """A row of `tickets`. `ticket_id` is generated by the database from `ticket_number`."""

    __tablename__ = "tickets"

    ticket_number: Mapped[int] = mapped_column(
        BigInteger, primary_key=True, server_default=text("nextval('ticket_number_seq')")
    )
    ticket_id: Mapped[str] = mapped_column(
        Text, Computed("'TCK-' || ticket_number::text", persisted=True)
    )
    customer_id: Mapped[UUID]
    order_id: Mapped[str | None] = mapped_column(Text)
    status: Mapped[str] = mapped_column(Text)
    handling_mode: Mapped[str] = mapped_column(Text)
    is_authority_required: Mapped[bool] = mapped_column(server_default=text("false"))
    source: Mapped[str] = mapped_column(Text)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    handling_started_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    closed_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))


class CustomerMessageRow(TicketsTables):
    """A row of `customer_messages`: one per ticket, never updated. The body is Confidential."""

    __tablename__ = "customer_messages"

    message_id: Mapped[UUID] = mapped_column(primary_key=True)
    ticket_id: Mapped[str] = mapped_column(Text)
    body: Mapped[str] = mapped_column(Text)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
